use crate::{config::Options,model::*};
// A18 decision: the caller's real options drive lowering (blueprint P0-S05
// `sheet_blocks(sheet, opts)`) — no more silent `Options::default()` here.
pub fn extract_csv(bytes:&[u8],meta:Meta,delimiter:u8,opts:&Options)->Document{let raw=String::from_utf8_lossy(bytes);let raw=raw.trim_start_matches('\u{feff}');let mut reader=::csv::ReaderBuilder::new().delimiter(delimiter).flexible(true).has_headers(false).from_reader(raw.as_bytes());let mut d=Document{meta,..Document::default()};let mut sheet=Sheet{name:std::path::Path::new(&d.meta.source_filename).file_stem().and_then(|s|s.to_str()).unwrap_or("Sheet1").into(),..Sheet::default()};
 for (r,row) in reader.records().enumerate(){match row{Ok(row)=>{for (c,s) in row.iter().enumerate(){if !s.is_empty(){sheet.cells.insert((r as u32,c as u32),Cell{reference:super::cell_ref(r as u32,c as u32),display:s.into(),kind:if s.parse::<f64>().is_ok(){CellKind::Number}else{CellKind::Text},..Cell::default()});sheet.max_row=sheet.max_row.max(r as u32);sheet.max_col=sheet.max_col.max(c as u32)}}},Err(_)=>d.warnings.push(format!("CSV record {} could not be decoded",r+1))}}
 d.meta.worksheet_count=Some(1);d.blocks=super::sheet_blocks(&sheet,opts);if sheet.max_row>=200||sheet.max_col>=20{d.warnings.push("large/irregular sheet exported as CSV listing".into())}d.workbook=Some(Workbook{title:None,sheets:vec![sheet]});d}
